#!/bin/bash
# Local driver: train one SOLVE-only control run (train.sh), then evaluate its step-75 adapter on SOLVE dev (200) and
# the 200 questions of phase2/failure_driven/data/val_uids.json, 4 samples, the matrix protocol (eval_matrix.py).
#   bash phase2/mix_control/scripts/run.sh ctrl-s0 0 8470 node04 [lr] [env: wait|ready]
# JOBTAG (environment variable, optional): appended to the Slurm job names (launch.py refuses a reused name).
# EXISTING_JOB (environment variable, optional): wait for this training job instead of submitting one.
# Do not edit this file while a driver runs it: bash reads it as it goes.
# env ready: the node already holds a complete mirror (node06), mark it ready (ready_env.sh); wait: push_env.sh fills it.
set -uo pipefail
cd "$(dirname "$0")/../../.."
RUN=$1; SEED=$2; PORT=$3; NODE=$4; LR=${5:-2e-5}; TAG=${JOBTAG:-}
HOST=mukund.hebbar@turing.iiit.ac.in
F='post-quantum|store now|openssh.com/pq'
R=/scratch/mukund.hebbar/mix-control
W=local/mix-control
WAIT="bash phase2/failure_driven/scripts/${6:-wait}_env.sh"
log() { echo "$(date '+%F %H:%M') [$RUN] $*"; }
t() { timeout 300 ssh -n -o BatchMode=yes $HOST "$@" 2>&1 | grep -v -E "$F"; }
submit() {
  while true; do
    out=$(t "cd ~/anlp-project-grpo && python3 scripts/turing/launch.py reconcile >/dev/null 2>&1; python3 scripts/turing/launch.py submit $*")
    id=$(echo "$out" | grep -oE '"job_id": [0-9]+' | grep -oE '[0-9]+')
    [ -n "$id" ] && { echo "$id"; return; }
    echo "$out" | grep -q refused || { log "submit failed: $out" >&2; exit 1; }
    sleep 120
  done
}
wait_job() {
  while true; do
    local s; s=$(t "sacct -j $1 -X -n -o State | head -1 | tr -d ' '" | tail -1)
    case "$s" in COMPLETED) return;; FAILED|CANCELLED*|TIMEOUT|OUT_OF_ME*|NODE_FAIL) log "job $1 $s"; exit 1;; esac
    sleep 60
  done
}
mkdir -p $W/evals  # rsync does not create the parent folder
if [ -z "$(t "ls /scratch/$NODE/mukund.hebbar/mix-control/runs/$RUN/adapters/step75/adapter_model.safetensors 2>/dev/null")" ]; then
  if [ -n "${EXISTING_JOB:-}" ]; then id=$EXISTING_JOB  # re-attach to a training job already submitted
  else id=$(submit --name mc-$RUN$TAG --node $NODE --gpus 2 --hours 9 -- $WAIT bash phase2/mix_control/scripts/train.sh $RUN $SEED $PORT $LR); fi
  log "training job $id"; wait_job $id
  [ -n "$(t "ls /scratch/$NODE/mukund.hebbar/mix-control/runs/$RUN/adapters/step75/adapter_model.safetensors 2>/dev/null")" ] || { log "no step-75 adapter"; exit 1; }
fi
timeout 300 rsync -a -e "ssh -o BatchMode=yes" $HOST:/scratch/$NODE/mukund.hebbar/mix-control/runs/$RUN/metrics.jsonl $W/$RUN-metrics.jsonl 2>&1 | grep -v -E "$F"
for sp in dev val200; do n=$sp-$RUN-step75
  if [ $sp = dev ]; then split="--split dev"; else split="--split uids --uids-file phase2/failure_driven/data/val_uids.json"; fi
  id=$(submit --name mc-$n$TAG --node $NODE --gpus 1 --hours 3 -- $WAIT python scripts/turing/eval_matrix.py --name mc-$n \
    --adapter $R/runs/$RUN/adapters/step75 $split --tasks solve --samples 4 --samples-tasks solve --out $R/evals/$n)
  log "$n job $id"; wait_job $id
  timeout 900 rsync -a --include='*/' --include='scores.jsonl' --include='metadata.json' --exclude='*' \
    -e "ssh -o BatchMode=yes" $HOST:/scratch/$NODE/mukund.hebbar/mix-control/evals/$n/ $W/evals/$n/ 2>&1 | grep -v -E "$F"
done
log "$RUN done: trained 75 steps, step-75 dev + val200 evaluated"
